#ifndef BITCOIN_TEST_UTIL_PSBT_VECTORS_H
#define BITCOIN_TEST_UTIL_PSBT_VECTORS_H

#include <string>

// Golden PSBT vectors (hex-encoded raw PSBT bytes) pinning the MWEB PSBT
// wire format.
//
// Two kinds of vectors live here:
//
//  * Deterministic vectors (PSBT_V2_ALLFIELDS): byte-reproducible from the
//    builders in test/util/psbt.h. psbt_vector_gen/gen_allfields_check
//    asserts builder output == pinned bytes.
//
//  * Crypto-bearing vectors (PSBT_MWEB_SIGNED etc.): produced once by the
//    generator cases in wallet/test/psbt_vector_gen.cpp and pinned as-is.
//    MWEB signing draws random blinds/ephemeral keys, so regenerating yields
//    different (but equally valid) bytes -- consuming tests must only assert
//    pinned-byte round-trips and cryptographic verification, never
//    generator-output == pinned bytes.
//
// Regeneration policy: if a consuming test starts failing, first decide
// whether the serialization change was intentional. If yes, rerun the
// psbt_vector_gen case(s) with
//   src/test/test_litecoin --run_test=psbt_vector_gen/<case> --log_level=message
// paste the new hex here, and commit the vector update in the same commit as
// the format change with an explanation. If no, the vector caught a
// serialization regression: fix the code, not the vector. Never regenerate
// just to make tests pass.

namespace psbt_test {

//! PSBTv2 exercising every keytype in every map: one canonical + one MWEB
//! input (0x90-0x99, 0x9C), one canonical + one MWEB output (0x90-0x98), one
//! kernel with all of 0x00-0x08 (incl. two indexed pegouts), globals
//! 0x90/0x91/0x92, fallback locktime, tx modifiable, and one unknown and one
//! proprietary key per map. Byte-reproducible via psbt_test::AllFieldsPSBT().
//! Not cryptographically valid.
inline const std::string PSBT_V2_ALLFIELDS =
    "";

//! Complete MWEB-to-MWEB PSBTv2: one MWEB input (100k, real Schnorr sig with
//! stealth-key feature), one MWEB output to MWEBTestKeys::Create().Address(0)
//! (90k, valid rangeproof + sender sig), one fee kernel (10k, signed), both
//! global offsets. Generator asserted: IsComplete(),
//! PSBTInputSignedAndVerified, FinalizePSBT succeeds, and the extracted
//! transaction's mweb_tx validates. Generated by psbt_vector_gen/gen_mweb_signed.
inline const std::string PSBT_MWEB_SIGNED =
    "";

//! An independent second signing of the same pre-sign structure as
//! PSBT_MWEB_SIGNED (same output id/amounts/recipient; different random
//! blinds and ephemeral keys). For merge-conflict tests: structurally
//! compatible, cryptographically conflicting.
//! Generated by psbt_vector_gen/gen_mweb_signed_alt.
inline const std::string PSBT_MWEB_SIGNED_ALT =
    "";

//! Peg-in PSBT after MWEB signing: one canonical vout carrying the final
//! GetScriptForPegin(kernel_id) script (100k), a signed peg-in kernel
//! (pegin 100k, fee 10k), one final MWEB output (90k), both offsets. No
//! canonical or MWEB inputs. Generator asserted the script's kernel ID equals
//! the kernel's GetKernelID(). Generated by psbt_vector_gen/gen_pegin_signed.
inline const std::string PSBT_PEGIN_SIGNED =
    "";

//! Mixed canonical+MWEB PSBT, fully final: one canonical wpkh input
//! (witness_utxo 110k, signed with MWEBTestKeys::ToCKey(TestSecret('7'))
//! after MWEB signing so the signature commits to the rewritten peg-in
//! script), the peg-in vout + signed peg-in kernel, and one final MWEB
//! output. Generator asserted FinalizePSBT succeeds.
//! Generated by psbt_vector_gen/gen_mixed_signed.
inline const std::string PSBT_MIXED_SIGNED =
    "";

//! MWEB input (100k, signed) + peg-out kernel (pegout 50k to a fixed wpkh
//! script, fee 10k, signed) + MWEB change output (40k), both offsets.
//! Generated by psbt_vector_gen/gen_pegout_signed.
inline const std::string PSBT_PEGOUT_SIGNED =
    "";

} // namespace psbt_test

#endif // BITCOIN_TEST_UTIL_PSBT_VECTORS_H
